import React from 'react';
import CircleButton from '../../components/CircleButton/CircleButton';
import './TopSection.scss';
import imgs1 from '../../assets/images/my-img1.jpeg';
import imgs2 from '../../assets/images/my-img2.jpg';
import imgs3 from '../../assets/images/my-img3.jpg';
import imgs4 from '../../assets/images/my-img4.jpg';
import imgs5 from '../../assets/images/my-img3.jpg';
import imgs6 from '../../assets/images/my-img4.jpg';
import { CommonConfig, Icons } from '../../config';

class TopSection extends React.Component {

    componentDidMount() {
        if (this.pathElement) {
            const signatureLength = this.pathElement.getTotalLength();
            this.pathElement.setAttribute('stroke-dasharray', signatureLength);
            this.pathElement.setAttribute('stroke-dashoffset', signatureLength);

            const viewBoxCoords = CommonConfig.signature?.viewBox.split(' ').map(val => parseInt(val));
            this.pathElement.setAttribute('stroke-width', Math.max(...viewBoxCoords) / 100);
        }
    }

    render() {

        const date = "Apr 2022 - Aug 2024";
        const [startStr, endStr] = date.split(" - ");
        const start = new Date(startStr);
        const end = new Date(endStr);
        const totalMonths = (end.getFullYear() - start.getFullYear()) * 12 + (end.getMonth() - start.getMonth());
        const years = Math.floor(totalMonths / 12);
        const months = totalMonths % 12;
        const duration = `${years} years ${months} months`;
        return (
            <div className="top-section">
                <div className="intro">
                    <h1>{CommonConfig.name}</h1>
                    <p>{CommonConfig.tagline}</p>
                </div>
                <div className="signature">
                    {/* <svg viewBox={CommonConfig.signature?.viewBox}>
                        <path ref={pathElement => {
                            this.pathElement = pathElement;
                        }} id="signature-path" stroke="var(--text-primary)" fill="none"
                            d={CommonConfig.signature?.signaturePathD} />
                    </svg> */}
                    {/* <img src={imgs2} /> */}
                    <div class="gallery">
                        <img src={imgs1} />
                        <img src={imgs2} />
                        <img src={imgs3} />
                        <img src={imgs4} />
                        <img src={imgs5} />
                        <img src={imgs6} />
                    </div>
                </div>
                <div className='head-tag'>
                    <div className='head-tag-desc'>I have {duration} of experience as a coding enthusiast and 4 years as a professional developer, working mostly with Angular, and 2 years of hands-on experience with React.</div>
                </div>
                <div className="social">
                    {CommonConfig.social.map((socialDetails, index) => {
                        return (
                            <CircleButton key={'top-section-social-' + index} tooltip={socialDetails.name} tooltipPlacement="left"
                                link={socialDetails.link} target="_blank">
                                {/* If the social platform icon is given then use that else pick from default icons */}
                                {socialDetails.icon
                                    ? socialDetails.icon : Icons[socialDetails.name.toLowerCase()]}
                            </CircleButton>
                        );
                    })}
                </div>
            </div>
        );
    }
}

export default TopSection;