import React from 'react';
import Section from '../Section/Section';
import { CustomSectionsConfig, ProjectSections, ProjectsConfig } from '../../config';
import './CustomSections.scss';

class CustomSections extends React.Component {
    render() {
        return (
            <>
                <div className="section-wrapper">
                    <div className='section'>
                        {ProjectSections.map((project, index) => (
                            <div
                                key={'section-' + index}
                                ref={this.props.sectionRefs[project.name]}
                                sectionHeader={project.name}>
                                <div class="heading-sec">
                                    <h2>{project.title}</h2>
                                </div>
                                {project.Projects.map((section, index) => (
                                    <div className="flex-container">
                                        <div className="custom-flex-box">
                                            <span class="vertical-flex">
                                                <span class="text-leading">{section.title}
                                                    <span class="responsive-text">({section.duration})</span>
                                                </span>
                                                <span class="custom-text-company">{section.company}</span>
                                            </span>
                                            <span class="responsive-hide">{section.duration}</span>
                                        </div>

                                        <div className="techStack-list">
                                            <span className="techStack-list-span">
                                                <div className="techStack-list-desc">
                                                    {section.techStack.map((techStack) => (
                                                        <div className="techStack-list-val">
                                                            <img src={techStack.icon} width="12" height="12" /> {techStack.name}</div>
                                                    ))}
                                                </div>
                                            </span>
                                            {section.Desc.map((Desc) => (
                                                <div>
                                                    <span>{Desc.name}</span>
                                                    <ul className="res-list">
                                                        {Desc.details.map((details) => (
                                                            <li>{details}</li>
                                                        ))}
                                                    </ul>
                                                </div>
                                            ))}
                                        </div>

                                    </div>
                                ))}
                            </div>
                        ))}

                        {ProjectsConfig.map((projects, index) => (
                            <div key={'section-' + index}
                                ref={this.props.sectionRefs[projects.name]}
                                sectionHeader={projects.name}>
                                <div className="heading-sec">
                                    <h2>{projects.name}</h2>
                                </div>

                                {projects.projects.map((sections, subIndex) => (
                                    <div key={subIndex} style={{ display: "flex", flexWrap: "wrap" }}>
                                        <p>{sections.name}</p>
                                        <p>{sections.description}</p>
                                        <div className="row" style={{ display: "flex", flexWrap: "wrap" }}>
                                            <div
                                                key={subIndex}
                                                style={{
                                                    flex: `${100 / 2}%`,
                                                    padding: "4px",
                                                }}
                                            >
                                                {/* <img src={sections.img} alt={`img-${subIndex}`} style={{ width: "100%" }} /> */}
                                            </div>
                                        </div>
                                    </div>

                                ))}
                            </div>
                        ))}
                    </div>
                </div>




                {CustomSectionsConfig.map((section, index) => (
                    <Section
                        key={'section-' + index}
                        ref={this.props.sectionRefs[section.name]}
                        sectionHeader={section.name}
                        headerIcon={section.headerIcon}
                        extraClass={section.extraClass ? section.extraClass : ''}
                    >
                        {section.content}
                    </Section>
                ))}
            </>
        );
    }
}

export default CustomSections;